package com.example.lending.domain;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

public class Book {

    private final UUID id;
    private final String title;
    private BookStatus status;
    // 예약 대기열. 맨 앞이 가장 먼저 대출할 수 있는 예약자다
    private final List<Reservation> reservations;

    private Book(UUID id, String title, BookStatus status, List<Reservation> reservations) {
        this.id = Objects.requireNonNull(id, "id");
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("title must not be blank");
        }
        this.title = title;
        this.status = Objects.requireNonNull(status, "status");
        this.reservations = new ArrayList<>(Objects.requireNonNull(reservations, "reservations"));
    }

    public static Book register(String title) {
        return new Book(UUID.randomUUID(), title, BookStatus.AVAILABLE, List.of());
    }

    public static Book reconstitute(UUID id, String title, BookStatus status, List<Reservation> reservations) {
        return new Book(id, title, status, reservations);
    }

    // 대출 중인 책에만 예약할 수 있다. 줄의 맨 뒤에 선다
    public Reservation reserve(UUID memberId) {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.AVAILABLE) {
            throw new BookAvailableException(id);
        }
        if (reservations.stream().anyMatch(r -> r.getMemberId().equals(memberId))) {
            throw new AlreadyReservedException(id, memberId);
        }
        Reservation reservation = Reservation.place(memberId);
        reservations.add(reservation);
        return reservation;
    }

    // 예약이 남아 있으면 맨 앞 예약자만 빌릴 수 있고, 빌리는 순간 그 예약은 소진된다
    public Loan loanTo(UUID memberId, LocalDate loanedAt) {
        if (status == BookStatus.DISCARDED) {
            throw new BookDiscardedException(id);
        }
        if (status == BookStatus.ON_LOAN) {
            throw new BookAlreadyOnLoanException(id);
        }
        if (!reservations.isEmpty()) {
            if (!reservations.get(0).getMemberId().equals(memberId)) {
                throw new BookReservedForOtherException(id);
            }
            reservations.remove(0);
        }
        Loan loan = Loan.start(id, memberId, loanedAt);
        status = BookStatus.ON_LOAN;
        return loan;
    }

    // 대출 중인 책은 폐기할 수 없다. 이미 폐기된 책을 다시 폐기해도 상태는 그대로 둔다
    public void discard() {
        if (status == BookStatus.ON_LOAN) {
            throw new CannotDiscardBookOnLoanException(id);
        }
        status = BookStatus.DISCARDED;
    }

    public void returnLoan(Loan loan, LocalDate returnedAt) {
        if (!loan.getBookId().equals(id)) {
            throw new IllegalArgumentException("loan does not belong to book: " + id);
        }
        loan.markReturned(returnedAt);
        status = BookStatus.AVAILABLE;
    }

    public UUID getId() {
        return id;
    }

    public String getTitle() {
        return title;
    }

    public BookStatus getStatus() {
        return status;
    }

    public List<Reservation> getReservations() {
        return List.copyOf(reservations);
    }
}
package com.example.lending.domain;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null);
    }

    // 반납 처리는 Book.returnLoan을 통해서만 (책 상태와 대출 상태가 함께 바뀌도록 package-private)
    void markReturned(LocalDate returnedAt) {
        if (this.returnedAt != null) {
            throw new AlreadyReturnedException(id);
        }
        Objects.requireNonNull(returnedAt, "returnedAt");
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt);
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    // 기한 당일 반납은 연체가 아니다. 기한을 넘긴 날짜 수만큼 연체일이 된다.
    public long getOverdueDays() {
        if (returnedAt == null) {
            throw new IllegalStateException("loan is not returned yet: " + id);
        }
        if (!returnedAt.isAfter(dueAt)) {
            return 0;
        }
        return ChronoUnit.DAYS.between(dueAt, returnedAt);
    }

    public long getLateFee() {
        return getOverdueDays() * LATE_FEE_PER_DAY;
    }
}
