        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findByIdForUpdate(loanId).map(loanMapper::toDomain);
    }

    @Override
    public List<ActiveLoan> loadActiveLoans(UUID memberId, int page, int size) {
        return loanJpaRepository.findActiveLoans(memberId, PageRequest.of(page, size)).stream()
                .map(row -> new ActiveLoan(row.loanId(), row.bookId(), row.title(), row.loanedAt(), row.dueAt()))
                .toList();
    }

    @Override
    public List<LoanHistory> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findLoanHistory(memberId).stream()
                .map(row -> new LoanHistory(
                        Loan.reconstitute(row.loanId(), row.bookId(), row.memberId(), row.loanedAt(), row.dueAt(),
                                row.returnedAt()),
                        row.title()))
                .toList();
    }
}
